{
  "positionId": "P06",
  "interviews": [
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "잠재 거래처 담당자와의 첫 접촉을 제품 소개 미팅으로 연결할 수 있는지 평가한다. 판단 초점은 담당자에게 실제로 건넬 미팅 제안이다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 신규 거래처 담당자에게 처음 전화하는 상황이다.",
          "task": "담당자에게 제품 소개 미팅을 제안한다.",
          "action": "담당자가 만날 필요를 느낄 수 있는 소개 내용과 구체적인 만남 요청을 실제 통화에서 사용할 말로 제시한다.",
          "result": "제안한 말이 담당자의 미팅 수락이나 일정 협의로 이어질 수 있음을 설명한다."
        },
        "expectedEvidence": [
          "담당자에게 실제로 건넬 제품 소개 미팅 제안 문구",
          "제안 문구에 담긴 만남의 필요성과 구체적인 미팅 요청"
        ]
      },
      "question": "입사 후 신규 거래처 담당자에게 처음 전화한다면, 첫 제품 소개 미팅을 잡는 제안을 어떤 말로 하시겠어요?",
      "answerTip": "실제로 말하듯 자연스럽게 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "제품 소개 미팅을 요청하는 말을 실제 통화에서 사용할 수 있는 구체적인 문장으로 제시한다.",
            "제안 문구에 담당자가 만날 필요를 이해할 내용과 수락 여부나 일정을 답할 수 있는 요청이 담겨 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "제품 소개 미팅을 요청하는 말을 제시하지만 표현이 포괄적이거나 상투적이다.",
            "만날 필요를 설명하는 내용이나 구체적인 만남 요청 중 일부가 부족하지만 미팅 제안이라는 뜻은 전달된다."
          ]
        },
        "poor": {
          "criteria": [
            "실제로 건넬 말 대신 적극적으로 연락하겠다는 다짐이나 영업 일반론만 제시한다.",
            "제품 설명이나 회사 소개에 그쳐 담당자에게 미팅을 제안하는 내용이 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P06-C1",
      "itemId": "P06-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기존 거래처의 불만과 발주 감소 신호에 맞춰 거래를 유지할 대응을 제안할 수 있는지 평가한다. 판단 초점은 납품 조건에 불편을 느끼는 거래처에 제시할 구체적인 대응이다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 기존 거래처가 납품 조건이 불편해 발주를 줄이겠다고 말하는 상황이다.",
          "task": "거래처의 불편에 대응해 거래를 이어 갈 제안을 한다.",
          "action": "납품 조건에서 느끼는 불편을 줄일 수 있는 대응을 거래처에 제안할 내용으로 설명한다.",
          "result": "제안한 대응으로 거래처의 불편을 줄이고 발주 감소를 완화할 수 있는 예상 효과를 설명한다."
        },
        "expectedEvidence": [
          "기존 거래처에 제안할 구체적인 거래 유지 대응",
          "제안 내용이 납품 조건의 불편과 발주 감소에 대응하는 연결점"
        ]
      },
      "question": "입사 후 기존 거래처에서 납품 조건이 불편해 발주를 줄이겠다고 한다면, 거래를 이어 갈 대응으로 무엇을 제안하시겠어요?",
      "answerTip": "생각을 정리한 뒤 간결하게 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "거래처에 제안할 수 있는 구체적인 납품 조건 조정이나 불편 해소 대응을 제시한다.",
            "제안 내용이 납품 조건의 불편을 줄여 거래를 이어 가는 데 직접 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "납품 조건을 조정하거나 불편을 해소하겠다는 제안을 하지만 바꿀 내용이 구체적이지 않다.",
            "거래를 유지하려는 대응 방향은 맞지만 제안이 거래처의 불편을 해소하는 연결점이 일부 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "불만을 듣거나 내부에 보고하겠다는 말에 그쳐 거래처에 제안할 대응을 제시하지 않는다.",
            "납품 조건의 불편과 무관한 판촉이나 일방적인 발주 요청만 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P12",
  "interviews": [
    {
